      <div class="f"><label>수량</label><input id="qt" type="number" min="1" value="1"></div>
      <div class="f"><label>요청 부서</label>
        <select id="dp"><option>기획과</option><option>총무과</option><option>홍보과</option><option>민원과</option></select></div>
      <button id="add">신청 추가</button>
    </div>
    <div class="msg" id="msg"></div>
  </div>
  <div class="card">
    <table><thead><tr><th>비품명</th><th>수량</th><th>부서</th><th>상태</th><th></th></tr></thead>
    <tbody id="tb"></tbody></table>
  </div>
</div>
<script>
const el=(t,c,txt)=>{const e=document.createElement(t);if(c)e.className=c;
  if(txt!==undefined&&txt!==null)e.textContent=String(txt);return e};
const put=(p,...k)=>{k.forEach(x=>{if(x!==null&&x!==undefined)p.append(x)});return p};
const $=id=>document.getElementById(id);
const kpi=(label,value)=>put(el("div","kpi"),el("b",null,label),el("span",null,value));
function toast(t){const m=$("msg");if(!m)return;m.textContent=t;m.classList.add("on");
  clearTimeout(m._t);m._t=setTimeout(()=>m.classList.remove("on"),2300)}
function clear(n){while(n.firstChild)n.removeChild(n.firstChild)}
const rows=[{n:"A4 복사용지",q:20,d:"기획과",s:"승인"},
 {n:"토너 카트리지",q:3,d:"총무과",s:"검토중"},
 {n:"화이트보드 마커",q:12,d:"홍보과",s:"승인"}];
function draw(){const tb=$("tb");clear(tb);
 if(!rows.length){const tr=el("tr");const td=el("td",null,"신청 내역이 없습니다");
  td.colSpan=5;td.style.textAlign="center";td.style.color="var(--muted)";td.style.padding="26px";
  put(tr,td);tb.append(tr);return}
 rows.forEach((r,i)=>{
  const tr=el("tr");
  put(tr,put(el("td"),el("b",null,r.n)),el("td",null,r.q+"개"),el("td",null,r.d),
   put(el("td"),el("span","tag "+(r.s==="승인"?"ok":"warn"),r.s)));
  const act=el("td");act.style.textAlign="right";
  const b=el("button","ghost","삭제");b.onclick=()=>{rows.splice(i,1);draw();toast("신청을 취소했습니다")};
  put(act,b);put(tr,act);tb.append(tr)})}
$("add").onclick=()=>{const n=$("nm").value.trim(),q=Number($("qt").value);
 if(!n){toast("비품명을 입력해 주세요");return}
 if(!(q>0)){toast("수량은 1개 이상이어야 합니다");return}
 rows.unshift({n:n,q:q,d:$("dp").value,s:"검토중"});
 $("nm").value="";$("qt").value=1;draw();toast("신청이 접수되었습니다")};
draw();
</script>
</body>
</html>
